function GLoaderCache.LoadShaders()
    if ResourceModule.IsEditorLoadAsset then return end
    local loaders = {}
    for i, v in ipairs(shaders) do
        if ResourceModule.IsResourceExist( ResourceModule.BundlesPathRelative .. v .. ".bytes") then
            local loader = ResourceModule.LoadBundleAsync(v, nil, true)
            table.insert(loaders, { loader = loader })
        end
    end
    while #loaders > 0 do
        for i, v in pairs(loaders) do
            ---@type Engine.Modules.AbstractResourceLoader
            local loader = v.loader
            if loader.IsCompleted then
                if not loader.IsError then
                    __cache[loader.Url] = {
                        loader = loader,
                        go = loader.ResultObject,
                        isReload = true
                    }
                    table.remove(loaders, i)
                else
                    table.remove(loaders, i)
                    loader:Release()
                    loader = nil
                end
            end
        end
        coroutine.yield()
    end
