function GLoaderCache.LoadMaterials()
    if not ResourceModule.IsEditorLoadAsset then
        ---如果assetbundle模式
        local detailBlurMat = 'shaders/ui/separated/[separated] ui-effectcapture-detailblur.mat'
        if ResourceModule.IsResourceExist(detailBlurMat) then
            local loader2 = ResourceModule.LoadBundleAsync(detailBlurMat, nil, true)
            while not loader2.IsCompleted do
                cs_coroutine.yield_return()
            end
            if loader2.IsSuccess then
                __cache[detailBlurMat] = {
                    loader = loader2,
                    go = loader2.ResultObject
                }
            end
        end
    end
end

