function GLoaderCache.Delete()
    for key, t in pairs(__cache) do
        if checkBool(t.isReload) then
            if string.contains(key,'builtin') or
                    string.contains(key,'3rd-party') or
                    string.contains(key,'fonts/alimedium.otf') or
                    string.contains(key,'textmesh') or
                    string.contains(key,'fonts/aliheavy.otf') then
            else
                --t.loader:Release(true)
                __cache[key] = nil
            end
        end
    end
end

function GLoaderCache.Reload()
    return cs_coroutine.start(function()
        GLoaderCache.Delete()
        cs_coroutine.yield_return(GLoaderCache.LoadShaders())
    end)
end

